/**
 * Minecraft version every plugin-based preset pins to, instead of tracking
 * itzg's default `LATEST`. Found via live testing, not assumed: right after
 * Minecraft's newest calendar release ("26.2"), EssentialsX's latest
 * published build only declared support up to 26.1.2 — MODRINTH_PROJECTS
 * refused to download it at all, which killed the container seconds into its
 * own init (a real failure this exact deploy reproduced and fixed). A brand
 * new MC version is exactly when plugins are MOST likely to be lagging, so
 * plugin-based presets deliberately don't chase LATEST — vanilla/creative/
 * hardcore/peaceful (no plugins) are unaffected and keep tracking LATEST.
 * Bump this only after re-verifying every plugin-based preset against the
 * new version, the same way this one was verified.
 */
export const FREEMC_PLUGIN_MC_VERSION = "26.1.2";

/** See waitForServerReady's doc comment — a plugins-kind preset needs real headroom beyond a plain boot's 110s. */
export const FREEMC_PLUGIN_READY_TIMEOUT_MS = 180_000;

/**
 * Given the two-axis gameType/gameMode a server is actually running, returns
 * the flat key the OLD FREEMC_PRESETS map used — the one and only place this
 * mapping is computed, so the legacy `FreeMinecraftServer.preset` column (kept
 * for the not-yet-migrated dashboard UI, see the schema comment) and the old
 * FREEMC_PRESETS-based cards it drives always agree with the real two-axis
 * state. vanilla+creative/hardcore/peaceful collapse to the old flat mode-only
 * keys (that's what they always meant); every other type just reports its own
 * key, since none of the 8 plugin-based types were ever combined with a
 * non-survival mode in the old flat scheme.
 */
export function legacyPresetKeyFor(gameType: string, gameMode: string): string {
  if (gameType === "vanilla" && (gameMode === "creative" || gameMode === "hardcore" || gameMode === "peaceful")) {
    return gameMode;
  }
  return gameType;
}

export type FreeMcPreset = {
  label: string;
  description: string;
  /** "properties": server.properties toggle only — write+restart on the SAME
   *  container (cheap, fast, what every preset used to be).
   *  "plugins": needs Paper + downloaded plugins baked in at container-creation
   *  time — env vars are immutable on a running container, so this ALWAYS goes
   *  through the same stop->remove->recreate path as a subdomain change (same
   *  data volume, world untouched), just with a different TYPE/plugin env set.
   *  Never silently "restart" a plugins preset — it would do nothing, since
   *  MODRINTH_PROJECTS/SPIGET_RESOURCES are read once at container creation. */
  kind: "properties" | "plugins";

/**
 * Inject `-e TYPE=<VARIANT>` into a Minecraft OsTemplate's setupScript from
 * `Server.gameVariant` (the customer's checkout choice — vanilla/paper/purpur/
 * fabric/forge, see lib/game-config.ts's MINECRAFT.variants).
 *
 * Found live 2026-08-30: this substitution never existed anywhere in the
 * provisioning pipeline. The OsTemplate's setupScript is one static string
 * with no `TYPE` at all, so `gameVariant` was captured at checkout, stored on
 * `Server`, and then completely ignored — every Minecraft customer got plain
 * Vanilla regardless of what they picked (or paid for a plugin-support tier
 * and had their manually-installed plugins never load, since Vanilla has no
 * plugin API at all). Diagnosed via a real customer ticket: the fix here is
 * minecraft-specific by design (it's the only family with a real variant
 * concept today) — generalize via `schemaFor(family)` if another family gains
 * one, rather than hardcoding a second family name here.
 *
 * Explicit and idempotent: always injects a `TYPE`, even for "vanilla" —
 * removes any reliance on the image's own default ever staying Vanilla — and
 * is a no-op if the script already names an explicit `TYPE` (never override
 * something a future per-family script sets on purpose).
 *
 * Kept in its own side-effect-free module (rather than inline in
 * worker/index.ts) so it can be unit tested directly — importing
 * worker/index.ts runs its top-level `main()` job-polling loop.
 */
import { schemaFor } from "../lib/game-config";

export function applyGameVariant(setupScript: string, family: string | null, variant: string | null): string {
  if (family !== "minecraft") return setupScript;
  if (!variant) return setupScript;
  if (/-e\s+TYPE=/.test(setupScript)) return setupScript;
  const type = variant.toUpperCase();
  return setupScript.replace(/(docker run\s+(?:-d|--detach)\b)/, `$1 -e TYPE=${type}`);
}

/**
 * The generalization this file's own docstring called for: substitute a
 * customer's checkout-time `Server.gameConfig` values into an OsTemplate's
 * setupScript, for whichever fields already appear in it as a docker
 * `-e KEY=...` env-var placeholder.
 *
 * Found live 2026-08-31 auditing DST (`dst` family): the whole per-family
 * customization schema in lib/game-config.ts (`ConfigField`, one per
 * `docker run -e KEY=...` in prisma/seed-wave4-games.ts and its Wave 1-3
 * predecessors) is captured at checkout into `Server.gameConfig`
 * (lib/game-order.ts) and shown in the post-deploy Settings tab, but — same
 * root cause as `applyGameVariant` above, just never generalized —
 * `provision()` in worker/index.ts never read it. Every family's setup
 * script always ran with its hardcoded static default (usually `''`),
 * regardless of what the customer entered at checkout. For most fields that
 * meant a cosmetically-wrong default (wrong MOTD, wrong hostname string);
 * for DST's `TOKEN` (an online DST cluster refuses to start with none — see
 * lib/game-config.ts's DST schema comment) it meant the container never
 * bound its port at all and PROVISION's own `checkGamePortOpen` health check
 * would time out and hard-fail the customer's paid order.
 *
 * Deliberately conservative: ONLY touches a key if the setupScript already
 * declares it as `-e KEY=...` — fields with no such placeholder (e.g. DST's
 * `PASSWORD`, which the yeetzone image never wired to an env var at all) are
 * left untouched rather than guessing a docker flag that isn't there.
 * Values are re-quoted as a single-quoted shell literal with proper `'`
 * escaping (`'\''`) so a customer-supplied string can never break out of the
 * quote and inject shell — the same safety property `validateConfig`'s own
 * control-character guard exists for, just extended to this second consumer
 * (a `docker run` command line) since the injection surface differs from a
 * line-oriented remote config file.
 */
/**
 * Substitute a freshly generated per-server secret into an OsTemplate's
 * setupScript, for a family whose image needs a real secret value that the
 * static catalog row can only ever leave blank — baking one directly into
 * the shared seed string (prisma/catalog.ts) would hand every future
 * customer the exact SAME value, since that row is one string shared by
 * every server of that family.
 *
 * Found live 2026-09-05 fixing a customer's "player list never loads"
 * ticket: the platform's own player-list/RCON feature (lib/game-control.ts)
 * requires Palworld's ADMIN_PASSWORD to be set (it doubles as the RCON auth
 * secret) and RCON's port published, but the catalog's setupScript set
 * neither — so no Palworld server, ever provisioned, could support the
 * player-list feature customers are paying for. RCON_ENABLED/RCON_PORT are
 * not secrets, so those went directly into prisma/catalog.ts's setupScript
 * string; only this one per-server value needs runtime substitution.
 *
 * Same conservative shape as applyGameConfigEnv: only touches a key that's
 * already present as `-e KEY=...` in the script, and the caller decides what
 * counts as a "secret" for a given family — this function has no per-family
 * knowledge of its own.
 */
export function applyGameControlSecrets(
  setupScript: string,
  secrets: Record<string, string>,
): string {
  let out = setupScript;
  for (const [key, value] of Object.entries(secrets)) {
    const re = new RegExp(`-e\\s+${key}=(?:'[^']*'|"[^"]*"|\\S*)`);
    if (!re.test(out)) continue;
    const escaped = value.replace(/'/g, `'\\''`);
    out = out.replace(re, `-e ${key}='${escaped}'`);
  }
  return out;
}

export function applyGameConfigEnv(
  setupScript: string,
  family: string | null,
  gameConfig: Record<string, unknown> | null | undefined,
): string {
  if (!family || !gameConfig) return setupScript;
  const schema = schemaFor(family);
  if (!schema) return setupScript;
  let out = setupScript;
  for (const field of schema.fields) {
    const raw = gameConfig[field.key];
    if (raw === undefined || raw === null) continue;
    const re = new RegExp(`-e\\s+${field.key}=(?:'[^']*'|"[^"]*"|\\S*)`);
    if (!re.test(out)) continue; // this field isn't docker-env-driven in this script — leave it alone
    const escaped = String(raw).replace(/'/g, `'\\''`);
    out = out.replace(re, `-e ${field.key}='${escaped}'`);
  }
  return out;
}

/**
 * Per-game customization schema (MVP).
