import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { connectionTarget, serverRootPassword } from "../lib/sftp";
import { withServerSsh, exec as sshExecOn } from "../lib/ssh-exec";
import { GAME_FAMILIES, type GameFamily } from "../lib/games";
import {
  judgeGameUpdate,
  parseGameUpdateOutput,
  updateCommand,
  updatesFromSteam,
} from "../lib/game-update-verify";
import type { Job } from "@prisma/client";

/**
 * Game-server auto-update handlers.
 *
 * `gameUpdate` runs the per-family update over SSH against the server's private
 * IP (the worker can reach vmbr1) and PROVES the outcome before saying anything
 * to the customer. `gameUpdateSweep` finds RUNNING game servers with
 * `autoUpdate=true` and enqueues GAME_UPDATE jobs for them — safe to call
 * periodically (it de-dupes on in-flight jobs).
 *
 * The remote command used to end `; true` with every step `|| true`, so it could
 * not exit non-zero and this handler always fired *"The latest server update was
 * applied and the service was restarted."* — unattended, every 6 hours, whether
 * or not steamcmd existed, a unit matched, or the service came back. The command
 * builder, the output parser and the verdict now live in lib/game-update-verify.ts
 * where they are tested; SSH failure is still a failure, but a clean SSH exit is
 * no longer evidence of anything.
 *
 * NOTE: `worker/index.ts` owns the job loop and its `handlers` map; wire these
 * in there (`GAME_UPDATE: gameUpdate`) and call `gameUpdateSweep()` on a timer.
 */

async function loadGameServer(serverId: string) {
  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { osTemplate: true, dedicatedIp: true, node: true },
  });
  if (!server) throw new Error(`Server ${serverId} not found`);
  return server;
}

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[game-update] notify failed", e);
  }
}

/**
 * Tell the customer once, not once per retry.
 *
 * The worker retries a failed job three times, and this one runs every six
 * hours; without this, a server whose steamcmd is missing would generate three
 * identical alarms per sweep, forever, and the customer would learn to ignore
 * them — which is the same outcome as not telling them.
 */
async function notifyFailureOnce(userId: string, serverId: string, title: string, body: string, href: string) {
  const since = new Date(Date.now() - 24 * 60 * 60_000);
  const dupe = await db.notification
    .findFirst({ where: { userId, title, createdAt: { gt: since } } })
    .catch(() => null);
  if (dupe) {
    console.error(`[game-update] ${serverId}: ${body} (customer already notified in the last 24h)`);
    return;
  }
  await notify(userId, title, body, href);
}

/** Run the per-family update over SSH and verify the result. */
export async function gameUpdate(job: Job): Promise<void> {
  const server = await loadGameServer(job.serverId!);
  if (SANDBOX) {
    // No VM exists, so nothing can be proven. Say that, rather than simulating a
    // success message the production path is no longer willing to send.
    await notify(
      server.userId,
      `${server.osTemplate.name} auto-update simulated on ${server.hostname} (sandbox)`,
      "Sandbox only — no server was contacted, nothing was updated and nothing was restarted.",
      `/dashboard/servers/${server.id}`
    );
    return;
  }
  const family = server.osTemplate.family as GameFamily;
  if (!GAME_FAMILIES.includes(family)) {
    throw new Error(`game update: ${server.hostname} is not a game server`);
  }
  if (server.status !== "RUNNING") throw new Error("game update: server is not running");
  const password = serverRootPassword(server);
  if (!connectionTarget(server) || !password) {
    throw new Error("game update: server has no IP/password yet");
  }
  const scrub = (s: string): string => (password ? s.split(password).join("***") : s);
  const href = `/dashboard/servers/${server.id}`;

  const remote = updateCommand(family);
  let stdout = "";
  let connError: string | null = null;
  try {
    // Host/port come from connectionTarget() (dedicated IP, or this server's
    // OWN node's public IP + its NAT-forwarded sshPort) — never the guest's
    // private bridge IP, which the worker has no route to for a non-primary node.
    const r = await withServerSsh(server, (conn) => sshExecOn(conn, remote, 600_000));
    stdout = r.stdout;
  } catch (e: any) {
    connError = scrub(String(e?.message ?? e));
  }

  // A non-zero exit (or a connection failure) is meaningful, but the markers may
  // still have been printed before whatever went wrong — check for them
  // regardless of how we got here and let the verdict decide, rather than
  // discarding evidence. Absence of the end marker is ALWAYS treated as an
  // unproven run, exit code notwithstanding — a clean SSH exit is not evidence.
  if (connError || !/^NXGU:END$/m.test(stdout)) {
    const detail = connError ?? (scrub(stdout).trim() || "no output — the update did not run to completion");
    const reason = `game update failed: ${detail}`;
    await notifyFailureOnce(
      server.userId,
      server.id,
      `${server.osTemplate.name} auto-update FAILED on ${server.hostname}`,
      `We could not reach or run the update on your server, so nothing was updated: ${detail.slice(0, 300)}`,
      href
    );
    throw new Error(reason);
  }

  const facts = parseGameUpdateOutput(scrub(stdout));
  const verdict = judgeGameUpdate({ family, hostname: server.hostname, facts });

  if (!verdict.ok) {
    await notifyFailureOnce(
      server.userId,
      server.id,
      `${server.osTemplate.name} auto-update did not complete on ${server.hostname}`,
      verdict.reason,
      href
    );
    // Failing the job is the point: it puts the reason in Job.error and in the
    // admin job list instead of leaving a green tick over a dead server.
    throw new Error(`game update not verified: ${verdict.reason}`);
  }

  // Only a real change is an event. This runs every 6 hours, so notifying on
  // every pass produced four "<game> updated on <host>" messages a day for a
  // server where nothing had been updated — the same erosion `notifyFailureOnce`
  // exists to prevent, and with a title that was not true.
  if (verdict.notify) await notify(server.userId, verdict.title, verdict.body, href);
  else console.log(`[game-update] ${server.hostname}: ${verdict.title} — ${verdict.body}`);
}

/**
 * Enqueue GAME_UPDATE jobs for every RUNNING game server that has opted into
 * auto-update and has no job already in flight. Idempotent / safe to call on a
 * timer. Returns nothing; logs a summary.
 */
export async function gameUpdateSweep(): Promise<void> {
  if (SANDBOX) return; // no game servers to update over SSH in the sandbox
  const candidates = await db.server.findMany({
    where: {
      status: "RUNNING",
      autoUpdate: true,
      osTemplate: { family: { in: [...GAME_FAMILIES] } },
    },
    select: { id: true, hostname: true, osTemplate: { select: { family: true } } },
  });
  if (candidates.length === 0) return;

  let enqueued = 0;
  for (const s of candidates) {
    const inflight = await db.job.count({
      where: { serverId: s.id, status: { in: ["QUEUED", "RUNNING"] } },
    });
    if (inflight > 0) continue;
    await db.job.create({ data: { type: "GAME_UPDATE", serverId: s.id } });
    enqueued++;
  }
  if (enqueued > 0) {
